import re, subprocess, sys
text = open("kb/public/claude/mods.md", encoding="utf-8").read()
items = []
for l in text.splitlines():
    if l.startswith("- "):
        items.append(l[2:])
    elif l.startswith("  ") and items:
        items[-1] += " " + l.strip()
ids = set(re.findall(r"^(S-\w+),", open("kb/public/_sources.csv", encoding="utf-8").read(), re.M))
def doc(f):
    m = re.search(r"\[DOC ([^\]]+)\]\s*$", f)
    return bool(m) and all(s.strip() in ids for s in m.group(1).split(","))
def has(*pats):
    return any(doc(f) and all(re.search(p, f, re.I) for p in pats) for f in items)
need = {
    "a hooks module imports only its own files by relative path": has(r"hooks module", r"import", r"relative path"),
    "passing $ to a function imported from another file fails claude plugin validate": has(r"validate", r"\$", r"imported|another file", r"fail|refus|reject|error"),
    "claude plugin test runs every *.test.ts with stubs for process.run, ui.notify and the clock": has(r"plugin test", r"\.test\.ts", r"process\.run", r"ui\.notify", r"clock"),
}
rc = subprocess.run([sys.executable, "_tools/rag.py", "facts", "public/claude/mods.md"], capture_output=True).returncode
print(need, "facts exit", rc)
sys.exit(0 if all(need.values()) and rc == 0 else 1)
